/**
 * OS convergence executor (Task: appliance-grade interface operations).
 *
 * Turns the pure plans from iface-os.ts into real host changes, behind four
 * guards — every write path (create/update/toggle/delete) funnels through
 * here, and so does the manual /api/v1/interfaces/apply endpoint:
 *
 *   gate        CONSOLE_OS_APPLY=1            off → plan preview, no exec
 *   tool        `ip` (iproute2) on the host
 *   whitelist   only `ip link|addr|route …` verbs generated by the planner
 *   protect     CONSOLE_OS_PROTECT (comma list, default "lo") — any step whose
 *               command names a protected interface is REFUSED before exec
 *               (the appliance must never be able to cut its own management
 *               access: on the Debian 13 appliance this is lo + ens32)
 *
 * Default-route ownership is enforced in the planner via `hostDefaultDev`:
 * this module queries `ip route show default` once and hands it to
 * buildApplyPlan, so a second WAN can never silently hijack the default.
 *
 * Convergence is best-effort with respect to the DB write: the console row is
 * the source of truth and is never rolled back because the host refused a
 * step — the outcome is returned to the caller and audited instead.
 */

import { readInterfaces } from "@/lib/host/proc";
import { hasTool, runTool } from "@/lib/host/tools";
import { buildApplyPlan, buildDeletePlan, osRowFor, type OsPlan } from "./iface-os";
import type { IfaceRuleView } from "./iface-rules";

export interface OsStepResult {
  cmd: string;
  ok: boolean;
  stderr?: string;
}

export interface OsApplyOutcome {
  /** "on" = exec attempted (or refused by a guard); "off" = preview only */
  gate: "on" | "off";
  applied: boolean;
  reason: string;
  plan: OsPlan;
  results?: OsStepResult[];
}

/** Interfaces the OS executor must never touch (management guard). */
export function protectedIfaces(): string[] {
  const raw = process.env.CONSOLE_OS_PROTECT?.trim();
  return (raw ? raw : "lo")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

/** Only iproute2 link/addr/route verbs generated by the planner may exec. */
const EXEC_WHITELIST = /^ip (link|addr|route) [a-z0-9].*$/;

/** Exact-token match so `br-lan` never collides with a protected `lan`. */
function protectedTarget(cmd: string, prot: ReadonlySet<string>): string | null {
  for (const tok of cmd.split(/[\s,]+/)) {
    if (prot.has(tok)) return tok;
  }
  return null;
}

/** dev of the host's current default route (null when none / unreadable). */
async function hostDefaultDev(): Promise<string | null> {
  const r = await runTool("ip route show default");
  if (!r.ok) return null;
  const m = /\bdev\s+(\S+)/.exec(r.stdout);
  return m ? m[1] : null;
}

async function execPlan(plan: OsPlan): Promise<OsApplyOutcome> {
  if (process.env.CONSOLE_OS_APPLY !== "1") {
    return {
      gate: "off",
      applied: false,
      reason:
        "OS convergence is disabled by platform policy on this installation — the plan above is a preview only",
      plan,
    };
  }
  if (!(await hasTool("ip"))) {
    return { gate: "on", applied: false, reason: "'ip' (iproute2) not found on the host — cannot execute the plan", plan };
  }

  const prot = new Set(protectedIfaces());
  for (const step of plan.steps) {
    const hit = protectedTarget(step.cmd, prot);
    if (hit) {
      return {
        gate: "on",
        applied: false,
        reason: `refused: step targets protected interface '${hit}' (management guard)`,
        plan,
      };
    }
    if (!EXEC_WHITELIST.test(step.cmd)) {
      return { gate: "on", applied: false, reason: "refused: plan step failed the iproute2 whitelist — execution aborted", plan };
    }
  }

  const results: OsStepResult[] = [];
  for (const step of plan.steps) {
    const r = await runTool(step.cmd);
    results.push({ cmd: step.cmd, ok: r.ok, stderr: r.ok ? undefined : r.stderr || r.error });
    if (!r.ok) break; // transactional: stop at first failure (rollback is P1)
  }
  const failed = results.filter((r) => !r.ok);
  return {
    gate: "on",
    applied: failed.length === 0,
    reason: failed.length === 0 ? "applied to host" : `${failed.length} step(s) failed`,
    plan,
    results,
  };
}

/** Build + (gate permitting) execute the convergence plan for one interface. */
export async function convergeIface(view: IfaceRuleView): Promise<OsApplyOutcome> {
  const [osIfaces, defDev] = await Promise.all([readInterfaces(), hostDefaultDev()]);
  const plan = buildApplyPlan(view, osRowFor(osIfaces, view.name), defDev);
  return execPlan(plan);
}

/** Build + (gate permitting) execute the teardown plan for a deleted interface. */
export async function teardownIface(view: IfaceRuleView): Promise<OsApplyOutcome> {
  const osIfaces = await readInterfaces();
  const plan = buildDeletePlan(view, osRowFor(osIfaces, view.name));
  if (plan.steps.length === 0) {
    return {
      gate: process.env.CONSOLE_OS_APPLY === "1" ? "on" : "off",
      applied: false,
      reason: "no host teardown needed (physical ports stay; interface not present on host)",
      plan,
    };
  }
  return execPlan(plan);
}

// ── safe wrappers — the DB write must never fail because the host did ───────

const failOutcome = (reason: string, plan: OsPlan): OsApplyOutcome => ({
  gate: process.env.CONSOLE_OS_APPLY === "1" ? "on" : "off",
  applied: false,
  reason,
  plan,
});

/** Never throws — OS convergence errors surface as an honest failed outcome. */
export async function convergeIfaceSafe(view: IfaceRuleView): Promise<OsApplyOutcome> {
  try {
    return await convergeIface(view);
  } catch (err) {
    return failOutcome(
      `convergence error: ${err instanceof Error ? err.message : "unknown"}`,
      { name: view.name, osName: null, steps: [] },
    );
  }
}

/** Never throws — same contract as convergeIfaceSafe for the delete path. */
export async function teardownIfaceSafe(view: IfaceRuleView): Promise<OsApplyOutcome> {
  try {
    return await teardownIface(view);
  } catch (err) {
    return failOutcome(
      `teardown error: ${err instanceof Error ? err.message : "unknown"}`,
      { name: view.name, osName: null, steps: [] },
    );
  }
}
